 legpress:['legs','glutes'],legpressh:['legs','glutes'],extension:['legs'],curl:['legs'],curllying:['legs'],hip:['glutes'],abductor:['glutes'],glute:['glutes'],
 pulldown:['back','arms'],row:['back','arms'],chest:['chest','arms'],pecdeck:['chest'],shoulder:['shoulders','arms'],lateral:['shoulders'],armcurl:['arms'],triceps:['arms'],crunch:['core'],calf:['calves']
